const cfg = $item(0).$node['Config'].json || {};
const state = $item(0).$node['Fetch Warmup Release State'].json || {};

function clean(v) { return String(v ?? '').trim(); }
function normalizePhone(v) {
  const digits = clean(v).replace(/\D/g, '');
  if (!digits) return '';
  if (digits.length === 11 && digits.startsWith('1')) return digits.slice(1);
  return digits;
}
function parseBoolean(v, fallback) {
  if (v === undefined || v === null || v === '') return fallback;
  if (typeof v === 'boolean') return v;
  const s = String(v).trim().toLowerCase();
  if (['true','1','yes','y'].includes(s)) return true;
  if (['false','0','no','n'].includes(s)) return false;
  return fallback;
}
function getContactsArray(data) {
  if (Array.isArray(data?.contacts)) return data.contacts;
  if (Array.isArray(data?.data?.contacts)) return data.data.contacts;
  return [];
}
function normalizeTagList(value) {
  if (Array.isArray(value)) return value.map((item) => clean(typeof item === 'string' ? item : item?.name || item?.value)).filter(Boolean);
  if (typeof value === 'string') return value.split(',').map((item) => clean(item)).filter(Boolean);
  return [];
}
function getWeekNumber() {
  const override = Math.trunc(Number(cfg.warmupWeekOverride || 0));
  if (override > 0) return override;
  const start = clean(cfg.rampStartDate);
  if (!start) return 1;
  const startDate = new Date(`${start}T00:00:00Z`);
  const now = new Date();
  if (Number.isNaN(startDate.getTime()) || now < startDate) return 1;
  const diffDays = Math.floor((now.getTime() - startDate.getTime()) / 86400000);
  return Math.floor(diffDays / 7) + 1;
}
function isValidTimeZone(tz) {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: tz });
    return true;
  } catch {
    return false;
  }
}
const usStateToTz = {
  AL:'America/Chicago', AK:'America/Anchorage', AZ:'America/Phoenix', AR:'America/Chicago', CA:'America/Los_Angeles', CO:'America/Denver', CT:'America/New_York', DE:'America/New_York', FL:'America/New_York', GA:'America/New_York', HI:'Pacific/Honolulu', ID:'America/Denver', IL:'America/Chicago', IN:'America/Indiana/Indianapolis', IA:'America/Chicago', KS:'America/Chicago', KY:'America/New_York', LA:'America/Chicago', ME:'America/New_York', MD:'America/New_York', MA:'America/New_York', MI:'America/New_York', MN:'America/Chicago', MS:'America/Chicago', MO:'America/Chicago', MT:'America/Denver', NE:'America/Chicago', NV:'America/Los_Angeles', NH:'America/New_York', NJ:'America/New_York', NM:'America/Denver', NY:'America/New_York', NC:'America/New_York', ND:'America/Chicago', OH:'America/New_York', OK:'America/Chicago', OR:'America/Los_Angeles', PA:'America/New_York', RI:'America/New_York', SC:'America/New_York', SD:'America/Chicago', TN:'America/Chicago', TX:'America/Chicago', UT:'America/Denver', VT:'America/New_York', VA:'America/New_York', WA:'America/Los_Angeles', WV:'America/New_York', WI:'America/Chicago', WY:'America/Denver', DC:'America/New_York'
};
const usStateNameToCode = {
  ALABAMA:'AL', ALASKA:'AK', ARIZONA:'AZ', ARKANSAS:'AR', CALIFORNIA:'CA', COLORADO:'CO', CONNECTICUT:'CT', DELAWARE:'DE', FLORIDA:'FL', GEORGIA:'GA', HAWAII:'HI', IDAHO:'ID', ILLINOIS:'IL', INDIANA:'IN', IOWA:'IA', KANSAS:'KS', KENTUCKY:'KY', LOUISIANA:'LA', MAINE:'ME', MARYLAND:'MD', MASSACHUSETTS:'MA', MICHIGAN:'MI', MINNESOTA:'MN', MISSISSIPPI:'MS', MISSOURI:'MO', MONTANA:'MT', NEBRASKA:'NE', NEVADA:'NV', 'NEW HAMPSHIRE':'NH', 'NEW JERSEY':'NJ', 'NEW MEXICO':'NM', 'NEW YORK':'NY', 'NORTH CAROLINA':'NC', 'NORTH DAKOTA':'ND', OHIO:'OH', OKLAHOMA:'OK', OREGON:'OR', PENNSYLVANIA:'PA', 'RHODE ISLAND':'RI', 'SOUTH CAROLINA':'SC', 'SOUTH DAKOTA':'SD', TENNESSEE:'TN', TEXAS:'TX', UTAH:'UT', VERMONT:'VT', VIRGINIA:'VA', WASHINGTON:'WA', 'WEST VIRGINIA':'WV', WISCONSIN:'WI', WYOMING:'WY', 'DISTRICT OF COLUMBIA':'DC'
};
const caProvinceToTz = { AB:'America/Edmonton', BC:'America/Vancouver', MB:'America/Winnipeg', NB:'America/Moncton', NL:'America/St_Johns', NS:'America/Halifax', NT:'America/Yellowknife', NU:'America/Iqaluit', ON:'America/Toronto', PE:'America/Halifax', QC:'America/Toronto', SK:'America/Regina', YT:'America/Whitehorse' };
const caProvinceNameToCode = { ALBERTA:'AB', 'BRITISH COLUMBIA':'BC', MANITOBA:'MB', 'NEW BRUNSWICK':'NB', NEWFOUNDLAND:'NL', 'NEWFOUNDLAND AND LABRADOR':'NL', 'NOVA SCOTIA':'NS', 'NORTHWEST TERRITORIES':'NT', NUNAVUT:'NU', ONTARIO:'ON', 'PRINCE EDWARD ISLAND':'PE', QUEBEC:'QC', SASKATCHEWAN:'SK', YUKON:'YT' };
function norm(v) { return String(v || '').trim(); }
function normState(v) { return norm(v).toUpperCase().replace(/\./g, '').replace(/\s+/g, ' '); }
function normCountry(v) { return norm(v).toUpperCase().replace(/\./g, '').replace(/\s+/g, ' '); }
function resolveContactTimezone(contact) {
  const explicit = norm(contact.timezone);
  if (explicit && isValidTimeZone(explicit)) return explicit;
  const stateNorm = normState(contact.state);
  const countryNorm = normCountry(contact.country);
  let stateCode = stateNorm;
  if (stateCode.length > 2) stateCode = usStateNameToCode[stateCode] || caProvinceNameToCode[stateCode] || stateCode;
  const usCodes = new Set(['US','USA','UNITED STATES','UNITED STATES OF AMERICA']);
  const caCodes = new Set(['CA','CAN','CANADA']);
  if (!countryNorm || usCodes.has(countryNorm)) {
    if (usStateToTz[stateCode]) return usStateToTz[stateCode];
  }
  if (caCodes.has(countryNorm) && caProvinceToTz[stateCode]) return caProvinceToTz[stateCode];
  if (usStateToTz[stateCode]) return usStateToTz[stateCode];
  if (caProvinceToTz[stateCode]) return caProvinceToTz[stateCode];
  return '';
}
async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}
async function apiRequest({ method, url, headers, body }) {
  const options = { method, url, headers, json: true };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
    };
  }
}

const locationId = clean(cfg.locationId);
const apiBaseUrl = clean(cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const apiKey = clean(cfg.apiKey);
const dryRun = parseBoolean($json?.body?.dryRun, !!cfg.defaultDryRun);
const candidateLimit = Math.max(1, Math.trunc(Number(cfg.candidateLimit || 200)));
const released = new Set(Array.isArray(state.released_contact_ids) ? state.released_contact_ids.map((v) => clean(v)).filter(Boolean) : []);
const sentToday = Math.max(0, Math.trunc(Number(state.sent_today || 0)));
const weekNumber = getWeekNumber();
const caps = JSON.parse(String(cfg.dailyCapsJson || '{"1":5,"2":10,"3":15}'));
const effectiveCap = Number(caps[String(Math.min(weekNumber, 3))] || caps['3'] || 15);
const remainingToday = Math.max(0, effectiveCap - sentToday);
const runId = `${new Date().toISOString()}__simpletexting_warmup_dispatch`;
const warnings = [];

if (!locationId) throw new Error('Missing Config.locationId');
if (!apiKey) throw new Error('Missing Config.apiKey');

if (remainingToday <= 0) {
  return [{ json: { status: 'summary', summary: { ok: true, dryRun, runId, weekNumber, effectiveCap, sentToday, remainingToday, fetched: 0, eligibleNow: 0, selected: 0, sent: 0, warnings: ['DAILY_CAP_REACHED'] } } }];
}

const searchBodyRaw = clean(cfg.ghlSearchBodyJson);
if (!searchBodyRaw) {
  return [{ json: { status: 'summary', summary: { ok: true, dryRun, runId, weekNumber, effectiveCap, sentToday, remainingToday, fetched: 0, eligibleNow: 0, selected: 0, sent: 0, warnings: ['CONFIGURE_GHL_SEARCH_BODY_JSON before activation.'] } } }];
}

let searchBody = {};
try {
  searchBody = JSON.parse(searchBodyRaw);
} catch {
  throw new Error('Config.ghlSearchBodyJson is not valid JSON');
}
searchBody.locationId = locationId;
if (searchBody.page == null) searchBody.page = 1;
if (searchBody.pageLimit == null) searchBody.pageLimit = candidateLimit;

const contactsRes = await apiRequest.call(this, {
  method: 'POST',
  url: `${apiBaseUrl}/contacts/search`,
  headers: {
    Authorization: `Bearer ${apiKey}`,
    Version: '2021-07-28',
    Accept: 'application/json',
    'Content-Type': 'application/json',
  },
  body: searchBody,
});
if (!contactsRes.ok) {
  return [{ json: { status: 'summary', summary: { ok: false, dryRun, runId, weekNumber, effectiveCap, sentToday, remainingToday, fetched: 0, eligibleNow: 0, selected: 0, sent: 0, warnings: ['CONTACT_SEARCH_FAILED'], error: contactsRes.data } } }];
}

const fetchedContacts = getContactsArray(contactsRes.data);
const eligibleNow = [];
for (const contact of fetchedContacts) {
  const contactId = clean(contact.id);
  const phone = normalizePhone(contact.phone);
  const tagNames = normalizeTagList(contact.tags || []);
  if (!contactId || !phone || released.has(contactId)) continue;
  if (tagNames.includes(clean(cfg.tagStop)) || tagNames.includes(clean(cfg.tagFinished)) || tagNames.includes(clean(cfg.tagOngoing))) continue;
  const tz = resolveContactTimezone(contact);
  if (!tz) continue;
  const localNow = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
  const localDay = localNow.getDay();
  const localHour = localNow.getHours();
  const isWeekday = localDay >= 1 && localDay <= 5;
  const withinHours = localHour >= Number(cfg.localWindowStartHour || 10) && localHour < Number(cfg.localWindowEndHour || 16);
  if (!isWeekday || !withinHours) continue;
  eligibleNow.push({
    contactId,
    email: clean(contact.email),
    phone,
    timezone: tz,
    localDay,
    localHour,
    firstName: clean(contact.firstName || contact.firstNameRaw),
    lastName: clean(contact.lastName || contact.lastNameRaw),
    tags: tagNames,
  });
}

const selected = eligibleNow.slice(0, remainingToday);
const outputs = [];
for (const contact of selected) {
  const payload = {
    dryRun,
    contactId: contact.contactId,
    contactPhone: contact.phone,
    templateKey: clean(cfg.defaultTemplateKey || 'sms_1'),
    campaignKey: clean(cfg.defaultCampaignKey || 'simpletexting_warmup'),
    addTags: [clean(cfg.tagStart), clean(cfg.tagOngoing)].filter(Boolean),
    removeTags: [clean(cfg.tagFinished)].filter(Boolean),
    contact: {
      first_name: contact.firstName,
      last_name: contact.lastName,
      email: contact.email,
    },
  };
  if (dryRun) {
    outputs.push({ json: { status: 'planned', ...contact, payload, run_id: runId, week_number: weekNumber } });
    continue;
  }
  const sendRes = await apiRequest.call(this, {
    method: 'POST',
    url: clean(cfg.simpletextingSendWebhookUrl),
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
      [clean(cfg.sendAuthHeaderName || 'x-lt-webhook-key')]: clean(cfg.sendAuthHeaderValue),
    },
    body: payload,
  });
  if (!sendRes.ok || sendRes.data?.ok === false) {
    outputs.push({ json: { status: 'error_send', ...contact, run_id: runId, week_number: weekNumber, details: sendRes.data || sendRes } });
    continue;
  }
  outputs.push({ json: { status: 'sent', ...contact, run_id: runId, week_number: weekNumber, campaign_key: payload.campaignKey, template_key: payload.templateKey, provider_message_id: clean(sendRes.data?.providerMessageId || sendRes.data?.providerResponse?.id), ghl_tag_sync: sendRes.data?.ghlTagSync || null } });
}

outputs.push({ json: { status: 'summary', summary: { ok: true, dryRun, runId, weekNumber, effectiveCap, sentToday, remainingToday, fetched: fetchedContacts.length, eligibleNow: eligibleNow.length, selected: selected.length, sent: outputs.filter((r) => r.json.status === 'sent').length, planned: outputs.filter((r) => r.json.status === 'planned').length, errors: outputs.filter((r) => r.json.status === 'error_send').length, warnings } } });
return outputs;

